using Godot;
using System;
public partial class MigrationScene {
 void ItemAccessory(Node3D root,int slot,int tier){Color cloth=new(.28f,.32f,.24f),plate=new(.32f,.38f,.36f);if(slot==11){Ellipsoid(root,new(0,.30f,0),new(.19f,.16f,.17f),tier==1?cloth:plate);Box(root,new(0,.24f,-.13f),new(.32f,.04f,.15f),cloth);}else for(int sign=-1;sign<=1;sign+=2){if(slot==12){Ellipsoid(root,new(sign*.12f,.2f,0),new(.075f,.13f,.045f),cloth);Box(root,new(sign*.12f,.23f,-.04f),new(.12f,.10f,.025f),plate);}else{Box(root,new(sign*.13f,.16f,.02f),new(.16f,.27f,.19f),cloth);Box(root,new(sign*.13f,.06f,-.08f),new(.17f,.10f,.32f),plate);}}}
 int shownWoundCount;
 void ShowWounds(){shownWoundCount=game.Life.Wounds.Count;var b=Panel("HEALTH / CONDITIONS / WATER");coopMenu="wounds";
  Text(b,$"Health {game.Life.Health:0}/{game.MaxHealth:0} / recoverable ceiling {game.RecoveryCeiling:0}\n"+game.Conditions+"\nBleeding drains health; there is no automatic bite-death timer. Bandages stop bleeding without healing HP. Patched wounds gradually heal. Trauma and illness lower natural recovery.");
  Text(b,$"CLEAN WATER {game.Craft.Water} / UNTREATED {game.Life.RawWater} / Untreated water has a 35% illness risk per drink. Clean water is safe. Existing bottled water remains clean.");
  var actions=new GridContainer{Columns=2};b.AddChild(actions);void Act(string title,string op,string data=""){Button(actions,title,()=>{if(!CoopRequest(op,data)){if(op=="purify")game.TreatWater(data=="filter");if(op=="rawdrink")game.Change(()=>game.Drink(true));if(op=="drink")game.Change(()=>game.Drink());if(op=="bandage")game.Change(()=>game.Life.Patch());if(op=="medicine")game.Change(()=>{if(game.Life.Medicine>0){game.Life.Medicine--;game.Life.Sickness=0;game.Life.RecoveryBoost=300;}});}ShowWounds();});}
  Act("PATCH MOST URGENT WOUND","bandage");Act("DRINK CLEAN WATER","drink");Act($"BOIL UP TO {(game.Life.SurvivalTech.Contains(5)?4:2)} / WORKBENCH + 2 TIMBER","purify","boil");Act(game.Life.SurvivalTech.Contains(1)?"MEMBRANE FILTER / 1 FUEL":"CHARCOAL FILTER / 1 RESIN","purify","filter");Act("DRINK UNTREATED / RISK ILLNESS","rawdrink");Act("USE MEDICAL KIT / CURE ILLNESS, SUPPORT RECOVERY","medicine");
  var scroll=new ScrollContainer{CustomMinimumSize=new(880,120)};b.AddChild(scroll);var rows=new VBoxContainer();scroll.AddChild(rows);for(int i=0;i<game.Life.Wounds.Count;i++){int index=i;var label=new Label();label.SetMeta("wound",i);rows.AddChild(label);if(game.Life.Wounds[i].Patched)Button(rows,"REMOVE BANDAGE / WOUND "+(i+1),()=>{if(!CoopRequest("unpatch",index.ToString()))game.Change(()=>game.Life.Unpatch(index));ShowWounds();});}
  Button(b,"BACK",CloseMenu);UpdateWoundPanel();
 }
 void UpdateWoundPanel(){if(coopMenu!="wounds"||menu==null)return;if(shownWoundCount!=game.Life.Wounds.Count){ShowWounds();return;}foreach(var node in menu.FindChildren("*","Label",true,false))if(node is Label l&&l.HasMeta("wound")){int i=(int)l.GetMeta("wound");if(i>=game.Life.Wounds.Count)continue;var w=game.Life.Wounds[i];l.Text=$"WOUND {i+1} / "+(w.Patched?$"PATCHED / heals in {Math.Max(0,w.Recovery)/60:0.0} minutes":"OPEN / draining health; H to bandage");}}
}